import csv

def load(f):
    with open(f, newline="") as fh:
        return list(csv.reader(fh))

for f in ["ae_death_age_gender.csv", "ae_tpd_age_gender.csv", "ae_ip_termination_by_month.csv"]:
    rows = load(f)
    print("=" * 40, f, "nrows:", len(rows) - 1)
    print("header:", rows[0])
    for r in rows[1:4]:
        print(r)
    ncols = len(rows[0])
    for i in range(min(ncols, 5)):
        vals = sorted(set(r[i] for r in rows[1:] if len(r) > i))
        if len(vals) <= 18:
            print("  col%d %s uniques:" % (i, rows[0][i]), vals)
        else:
            print("  col%d %s: %d uniques, first:" % (i, rows[0][i], len(vals)), vals[:6], "last:", vals[-3:])
